<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { FlaskConical, Pencil, Plus, ShieldCheck, Trash2, X } from 'lucide-vue-next'
import { api } from '../api'
import { tr } from '../preferences'
import type { ACLEvaluation, ACLRule, Device, ManagedGroup, ManagedUser } from '../types'

const records=ref<ACLRule[]>([]),users=ref<ManagedUser[]>([]),groups=ref<ManagedGroup[]>([]),devices=ref<Device[]>([])
const loading=ref(true),open=ref(false),saving=ref(false),error=ref(''),editing=ref<ACLRule>()
const evaluating=ref(false),evaluation=ref<ACLEvaluation>()
const permissionOptions=computed(()=>[['remote_control',tr('Удалённое управление','Remote control')],['view',tr('Просмотр','View')],['file_transfer',tr('Передача файлов','File transfer')],['clipboard',tr('Буфер обмена','Clipboard')],['tcp_tunnel',tr('TCP-туннель','TCP tunnel')],['terminal',tr('Терминал','Terminal')],['audio',tr('Аудио','Audio')],['camera',tr('Камера','Camera')],['manage',tr('Управление','Manage')]] as const)
const form=reactive({name:'',subject_type:'user_group',subject_id:'',target_type:'device_group',target_id:'',permissions:['remote_control'] as string[],effect:'allow' as 'allow'|'deny',priority:100,enabled:true})
const simulation=reactive({user_id:'',target_id:'',permission:'remote_control'})
const subjects=computed(()=>form.subject_type==='user'?users.value:groups.value.filter(group=>group.kind==='user'))
const targets=computed(()=>form.target_type==='device'?devices.value:groups.value.filter(group=>group.kind==='device'))
const label=(type:string,id:string)=>{if(!id)return tr('Все','All');if(type==='user')return users.value.find(v=>v.id===id)?.display_name||users.value.find(v=>v.id===id)?.username||id;if(type==='user_group'||type==='device_group')return groups.value.find(v=>v.id===id)?.name||id;return devices.value.find(v=>v.rustdesk_id===id)?.alias||devices.value.find(v=>v.rustdesk_id===id)?.hostname||id}
async function load(){loading.value=true;error.value='';try{[records.value,users.value,groups.value,devices.value]=await Promise.all([api.aclRules(),api.users(),api.groups(),api.devices()])}catch(e){error.value=e instanceof Error?e.message:tr('Ошибка загрузки ACL','Unable to load ACL')}finally{loading.value=false}}
function add(){editing.value=undefined;Object.assign(form,{name:'',subject_type:'user_group',subject_id:'',target_type:'device_group',target_id:'',permissions:['remote_control'],effect:'allow',priority:100,enabled:true});open.value=true}
function edit(rule:ACLRule){editing.value=rule;Object.assign(form,{name:rule.name,subject_type:rule.subject_type,subject_id:rule.subject_id,target_type:rule.target_type,target_id:rule.target_id,permissions:[...rule.permissions],effect:rule.effect||'allow',priority:rule.priority,enabled:rule.enabled});open.value=true}
function scopeChanged(side:'subject'|'target'){if(side==='subject')form.subject_id='';else form.target_id=''}
function togglePermission(permission:string){form.permissions=form.permissions.includes(permission)?form.permissions.filter(value=>value!==permission):[...form.permissions,permission]}
function payload(){return{name:form.name,subject_type:form.subject_type,subject_id:form.subject_id,target_type:form.target_type,target_id:form.target_id,permissions:form.permissions,effect:form.effect,priority:form.priority,enabled:form.enabled}}
async function save(){if(!form.permissions.length){error.value=tr('Выберите хотя бы одно разрешение','Select at least one permission');return}saving.value=true;error.value='';try{editing.value?await api.updateACLRule(editing.value.id,payload()):await api.createACLRule(payload());open.value=false;await load()}catch(e){error.value=e instanceof Error?e.message:tr('Ошибка сохранения','Save failed')}finally{saving.value=false}}
async function toggle(rule:ACLRule){saving.value=true;try{await api.updateACLRule(rule.id,{...rule,enabled:!rule.enabled});await load()}catch(e){error.value=e instanceof Error?e.message:tr('Ошибка обновления','Update failed')}finally{saving.value=false}}
async function remove(rule:ACLRule){if(!confirm(tr(`Удалить правило «${rule.name}»?`,`Delete rule “${rule.name}”?`)))return;saving.value=true;try{await api.deleteACLRule(rule.id);await load()}catch(e){error.value=e instanceof Error?e.message:tr('Ошибка удаления','Delete failed')}finally{saving.value=false}}
async function evaluate(){if(!simulation.user_id||!simulation.target_id)return;evaluating.value=true;error.value='';try{evaluation.value=await api.evaluateACL(simulation)}catch(e){error.value=e instanceof Error?e.message:tr('Не удалось проверить доступ','Unable to evaluate access')}finally{evaluating.value=false}}
onMounted(load)
</script>

<template><section class="section-heading"><div><p class="eyebrow">Pre-connection authorization</p><h2>{{tr('Контроль доступа','Access control')}}</h2><p>{{tr('Разрешения проверяются HBBS до PunchHole и Relay. Меньшее число приоритета применяется первым, а явный запрет сильнее разрешения при равном приоритете.','HBBS checks permissions before PunchHole and Relay. Lower priority numbers apply first, and an explicit deny wins at equal priority.')}}</p></div><button class="primary-button compact" @click="add"><Plus :size="17"/>{{tr('Добавить правило','Add rule')}}</button></section><p v-if="error" class="alert-error">{{error}}</p><article v-if="!loading" class="panel acl-simulator"><div class="panel-heading"><div><p class="overline">Policy simulator</p><h3>{{tr('Проверка эффективного доступа','Effective access test')}}</h3></div><FlaskConical :size="20"/></div><div class="acl-simulator-form"><label><span>{{tr('Пользователь','User')}}</span><select v-model="simulation.user_id"><option value="">{{tr('Выберите пользователя','Select user')}}</option><option v-for="user in users" :key="user.id" :value="user.id">{{user.display_name||user.username}}</option></select></label><label><span>{{tr('Целевое устройство','Target device')}}</span><select v-model="simulation.target_id"><option value="">{{tr('Выберите устройство','Select device')}}</option><option v-for="device in devices" :key="device.rustdesk_id" :value="device.rustdesk_id">{{device.alias||device.hostname||device.rustdesk_id}} · {{device.rustdesk_id}}</option></select></label><label><span>{{tr('Разрешение','Permission')}}</span><select v-model="simulation.permission"><option v-for="option in permissionOptions" :key="option[0]" :value="option[0]">{{option[1]}}</option></select></label><button class="secondary-button" :disabled="evaluating||!simulation.user_id||!simulation.target_id" @click="evaluate">{{evaluating?tr('Проверка…','Evaluating…'):tr('Проверить','Evaluate')}}</button></div><div v-if="evaluation" class="acl-result" :class="evaluation.allowed?'allowed':'denied'"><strong>{{evaluation.allowed?tr('Доступ разрешён','Access allowed'):tr('Доступ запрещён','Access denied')}}</strong><span>{{evaluation.reason}}<template v-if="evaluation.winning_effect"> · {{evaluation.winning_effect}} @ {{evaluation.winning_priority}}</template></span><details><summary>{{tr('Трассировка правил','Rule trace')}} · {{evaluation.matched_rule_ids.length}} / {{evaluation.enabled_rule_count}}</summary><div v-for="rule in evaluation.matched_rules" :key="rule.rule_id" class="acl-trace"><span>{{rule.name}}</span><span class="badge" :class="rule.effect==='deny'?'red':'green'">{{rule.effect}}</span><span>P{{rule.priority}}</span><span>{{rule.matched?tr('совпало','matched'):tr('не совпало','not matched')}}</span></div></details></div></article><p v-if="loading" class="panel empty-state">{{tr('Загрузка…','Loading…')}}</p><section v-else class="card-grid"><article v-for="rule in records" :key="rule.id" class="panel policy-card" :class="{inactive:!rule.enabled}"><span class="metric-icon"><ShieldCheck :size="20"/></span><div class="policy-content"><div><span class="badge" :class="rule.effect==='deny'?'red':'green'">{{rule.effect==='deny'?tr('Запретить','Deny'):tr('Разрешить','Allow')}}</span><span class="badge" :class="rule.enabled?'green':'neutral'">{{rule.enabled?tr('Включено','Enabled'):tr('Выключено','Disabled')}}</span><span class="badge neutral">{{tr('Приоритет','Priority')}} {{rule.priority}}</span></div><h3>{{rule.name}}</h3><p>{{label(rule.subject_type,rule.subject_id)}} → {{label(rule.target_type,rule.target_id)}}</p><div><span v-for="permission in rule.permissions" :key="permission" class="badge neutral">{{permissionOptions.find(v=>v[0]===permission)?.[1]||permission}}</span></div></div><div class="policy-actions"><button class="icon-btn" :title="tr('Редактировать','Edit')" @click="edit(rule)"><Pencil :size="16"/></button><button class="text-button" @click="toggle(rule)">{{rule.enabled?tr('Выключить','Disable'):tr('Включить','Enable')}}</button><button class="icon-action" :title="tr('Удалить','Delete')" @click="remove(rule)"><Trash2 :size="16"/></button></div></article><article v-if="!records.length" class="panel empty-state">{{tr('Правил пока нет. Пока список ACL пуст, подключение разрешается всем подтверждённым пользователям.','No rules yet. While ACL is empty, every approved user is allowed to connect.')}}</article></section>
<div v-if="open" class="modal-backdrop" @click.self="open=false"><form class="modal-card" @submit.prevent="save"><div class="modal-heading"><h3>{{editing?tr('Редактирование ACL','Edit ACL rule'):tr('Новое ACL-правило','New ACL rule')}}</h3><button type="button" class="icon-btn" @click="open=false"><X :size="20"/></button></div><label><span>{{tr('Название','Name')}}</span><input v-model="form.name" required minlength="2"/></label><div class="form-grid"><label><span>{{tr('Действие','Effect')}}</span><select v-model="form.effect"><option value="allow">{{tr('Разрешить','Allow')}}</option><option value="deny">{{tr('Запретить','Deny')}}</option></select></label><label><span>{{tr('Приоритет','Priority')}}</span><input v-model.number="form.priority" type="number" min="1" max="10000"/></label><label><span>{{tr('Субъект','Subject')}}</span><select v-model="form.subject_type" @change="scopeChanged('subject')"><option value="user">{{tr('Пользователь','User')}}</option><option value="user_group">{{tr('Группа пользователей','User group')}}</option></select></label><label><span>{{tr('Кто получает доступ','Who gets access')}}</span><select v-model="form.subject_id"><option value="">{{tr('Все пользователи','All users')}}</option><option v-for="value in subjects" :key="value.id" :value="value.id">{{'username' in value?(value.display_name||value.username):value.name}}</option></select></label><label><span>{{tr('Цель','Target')}}</span><select v-model="form.target_type" @change="scopeChanged('target')"><option value="device">{{tr('Устройство','Device')}}</option><option value="device_group">{{tr('Группа устройств','Device group')}}</option></select></label><label><span>{{tr('К каким устройствам','Target devices')}}</span><select v-model="form.target_id"><option value="">{{tr('Все устройства','All devices')}}</option><option v-for="value in targets" :key="'rustdesk_id' in value?value.rustdesk_id:value.id" :value="'rustdesk_id' in value?value.rustdesk_id:value.id">{{'rustdesk_id' in value?(value.alias||value.hostname||value.rustdesk_id):value.name}}</option></select></label><label v-if="editing" class="check-label"><input v-model="form.enabled" type="checkbox"/><span>{{tr('Правило включено','Rule enabled')}}</span></label></div><fieldset class="permission-picker"><legend>{{tr('Разрешения','Permissions')}}</legend><label v-for="option in permissionOptions" :key="option[0]" class="check-label"><input type="checkbox" :checked="form.permissions.includes(option[0])" @change="togglePermission(option[0])"/><span>{{option[1]}}</span></label></fieldset><div class="modal-actions"><button type="button" class="secondary-button" @click="open=false">{{tr('Отмена','Cancel')}}</button><button class="primary-button compact" :disabled="saving||!form.permissions.length">{{saving?tr('Сохранение…','Saving…'):tr('Сохранить','Save')}}</button></div></form></div></template>
